import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

/** Loads a golden fixture generated by scripts/generate-fixtures.php */
export function loadFixture<T>(name: string): T {
  const path = fileURLToPath(new URL(`./fixtures/${name}`, import.meta.url))
  return JSON.parse(readFileSync(path, 'utf8')) as T
}

/** Fixture byte strings: valid UTF-8 stays a string, other bytes are {hex} */
export type Bytes = string | { hex: string }

export const isHex = (b: Bytes | null): b is { hex: string } => b !== null && typeof b === 'object'

export function bytes(b: Bytes): Uint8Array {
  return isHex(b) ? Uint8Array.from(Buffer.from(b.hex, 'hex')) : new TextEncoder().encode(b)
}

/** The value as the API would carry it: strings stay strings, raw bytes become Uint8Array */
export function cell(b: Bytes | null): string | Uint8Array | null {
  if (b === null) return null
  return isHex(b) ? bytes(b) : b
}

/** Compare output strings with fixture bytes */
export function asText(b: Bytes): string {
  return isHex(b) ? new TextDecoder().decode(bytes(b)) : b
}
